package fft

// dct4FusedRoute is false on amd64: the fused scalar kernels are slower than the
// pooled path there (75 ns against 60 ns for one DCT-IV(64) on a Zen 4), so a
// single call keeps the pooled path. The pair forms of length 64 have an AVX2
// kernel.
const dct4FusedRoute = false

// dct4PairAsm says whether the pair forms run the AVX2+FMA kernels
// (dct4_64_amd64.s, generated by internal/gendct4): fmaAvailable, which is AVX2
// and FMA3. A plan reads it when it is built: without AVX2 and FMA3 its pair flag
// is false and the pair forms are two pooled calls. A variable so that a test can
// switch it off after the plan exists, which runs the scalar kernel twice (the
// branch of dct4Pair no real plan reaches).
var dct4PairAsm = fmaAvailable

// dct4PairRoute reports whether a new DCT-IV plan of length n routes its pair
// forms to the kernels: length 64 only (there is no AVX2 kernel of 128).
func dct4PairRoute(n int) bool { return n == 64 && dct4PairAsm }

// The pair kernels hold one complex value of both transforms in each 256-bit
// register (see internal/gendct4/amd64.go). They read all inputs of both streams
// before the first store; dst0 may alias src0 and dst1 may alias src1 but no other
// overlap is allowed (runPair checks). They spill to their own stack frame.

//go:noescape
func dct4n64YPairF64(dst0, dst1, src0, src1 *float64, w *dct4n64YTab)

//go:noescape
func dct4n64YPairF64S(dst0, dst1, src0, src1 *float64, w *dct4n64YTab, f float64)

//go:noescape
func dct4n64YPairF32(dst0, dst1, src0, src1 *float32, w *dct4n64YTab)

//go:noescape
func dct4n64YPairF32S(dst0, dst1, src0, src1 *float32, w *dct4n64YTab, f float64)

func dct4Pair(n int, dst0, dst1, src0, src1 []float64, f float64) {
	switch {
	case n != 64 || !dct4PairAsm:
		dct4Single(n, dst0, src0, f)
		dct4Single(n, dst1, src1, f)
	case f != 1:
		dct4n64YPairF64S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64Y, f)
	default:
		dct4n64YPairF64(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64Y)
	}
}

func dct4PairMixed(n int, dst0, dst1, src0, src1 []float32, f float64) {
	switch {
	case n != 64 || !dct4PairAsm:
		dct4SingleMixed(n, dst0, src0, f)
		dct4SingleMixed(n, dst1, src1, f)
	case f != 1:
		dct4n64YPairF32S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64Y, f)
	default:
		dct4n64YPairF32(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64Y)
	}
}
